-- Гилнеас, "Предательство в Пределе бури" (24592): сдать некому - Генн, Годфри и все рядом исчезли.
-- В 17:37 17.10.2026 за минуту (по таблице creature_respawn персонажей минус задержка возрождения) выбыли из игры король Генн 37876
-- (guid 802362, сдает 24592 и выдает 24677), лорд Годфри 37875 (802361), лорд Хьюэлл 38764 (802364, дает лошадь к 24677) и 6 стражников
-- Предела бури 37716 в радиусе 26 ярдов от Генна; из стражников уцелели только те, что дальше 35 ярдов. Возрождение у всех 7200 секунд (2 часа), поэтому до
-- 19:37 квест сдать нельзя, а для следующих игроков он ломается точно так же. Причину гибели установить нельзя (в логах ее нет),
-- поэтому закрыты оба правдоподобных пути:
-- 1) У шаблонов Генна, Годфри и Хьюэлла флаги unit_flags |= 0x100 (IMMUNE_TO_PC) | 0x200 (IMMUNE_TO_NPC): в этом ядре (Unit::_IsValidAttackTarget)
--    такое существо не атакуют другие НПС и оно не атакует НПС; игроки и так не могут нападать на дружественную фракцию 2173.
--    Стражники (фракция 1924, враждебны игрокам) остаются враждебными игрокам.
-- 2) Возрождение квестовых НПС 7200 -> 60 секунд, стражников и мастифа 7200 -> 120 секунд: если их все же убьют, они вернутся быстро.
-- Откат: unit_flags у 37875/37876/38764 вернуть значения 32768, 33024, 32768; spawntimesecs = 7200.
UPDATE `creature_template` SET `unit_flags` = `unit_flags` | 768 WHERE `entry` IN (37875, 37876, 38764) AND (`unit_flags` & 768) <> 768;
UPDATE `creature` SET `spawntimesecs` = 60 WHERE `guid` IN (802361, 802362, 802364) AND `spawntimesecs` = 7200;
UPDATE `creature` SET `spawntimesecs` = 120 WHERE `map` = 654 AND `id` IN (37716, 37718) AND `spawntimesecs` = 7200;

-- Сцена после сдачи 24592 (zone_duskhaven.cpp, npc_king_genn_greymane_37876): Генн говорит группу 0, Годфри говорит группу 0 (Talk(0)),
-- потом Годфри летит по пути waypoint_data с id = его guid (802361) и на 4-й точке исчезает (MovementInform 4). Для Годфри не было
-- ни реплики группы 0 (в creature_text только группа 3 - немецкий дубль), ни пути: после сдачи он молчал бы и зависал бы в воздухе
-- (SetDisableGravity) навсегда. Реплика - официальный текст 38633 ("No... I'd sooner die than have one of your kind for a king!", русский
-- берется из broadcast_text), путь взят из сценария ретейла smart_scripts 3787500 (Годфри бежит на (-2057.1, 937.7, 70), прыгает на
-- (-2058, 928, 71), потом на (-2059, 923, 60) и исчезает): добавлены еще три точки дальше по тому же направлению (путь из 6 точек,
-- чтобы 4-я точка гарантированно была не последней).
-- Откат: DELETE FROM creature_text WHERE CreatureID = 37875 AND GroupID = 0; DELETE FROM waypoint_data WHERE id = 802361.
DELETE FROM `creature_text` WHERE `CreatureID` = 37875 AND `GroupID` = 0 AND `ID` = 0;
INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`)
VALUES (37875, 0, 0, 'No... I''d sooner die than have one of your kind for a king!', 12, 0, 100, 0, 0, 19631, 38633, 0, 'Lord Godfrey to Player');
